SELECT s.id AS spot_id, s.name, s.theme, s.latitude, s.longitude,
ROUND(CAST( ST_Distance( s.location::geography, ST_SetSRID(ST_MakePoint(#{lng}, #{lat}), 4326)::geography ) / 1000.0 AS numeric ), 2)
NULL::numeric
AS distance_km, s.created_at AS created_at, s.status AS status FROM spots s WHERE s.user_id = #{userId} AND s.deleted_at IS NULL AND s.status IN
#{code}
ORDER BY s.created_at DESC, s.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM spots s
WHERE s.user_id    = #{userId}
  AND s.deleted_at IS NULL
  AND s.status IN

      #{code}
